UPDATE posts SET content = replace(content, 'What matters is whether any page you want to rank is on that list.', 'What matters is whether any page you want to rank is on that list. If one is, work out <a href="https://blog.scaryspiderseo.com/technical-seo/why-google-is-not-indexing-your-pages">why Google is not indexing it</a>.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'technical-seo-audit-checklist' AND instr(content, 'What matters is whether any page you want to rank is on that list.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/technical-seo/why-google-is-not-indexing-your-pages"') = 0;
UPDATE posts SET content = replace(content, 'That view shows how many of the URLs you asked Google to index actually made it in, and why the rest did not.', 'That view shows how many of the URLs you asked Google to index actually made it in, and why the rest did not. If key pages are missing, use this guide to <a href="https://blog.scaryspiderseo.com/technical-seo/why-google-is-not-indexing-your-pages">diagnose pages that are not indexed</a>.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'xml-sitemap-guide' AND instr(content, 'That view shows how many of the URLs you asked Google to index actually made it in, and why the rest did not.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/technical-seo/why-google-is-not-indexing-your-pages"') = 0;
UPDATE posts SET content = replace(content, 'In plain terms, a permanent redirect tends to put the new URL in search results, and a temporary one tends to keep the old URL there.', 'In plain terms, a permanent redirect tends to put the new URL in search results, and a temporary one tends to keep the old URL there. Redirects are one input into <a href="https://blog.scaryspiderseo.com/technical-seo/canonical-tags-explained">how Google picks a canonical URL</a>, alongside canonical tags and sitemaps.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = '301-vs-302-redirects' AND instr(content, 'In plain terms, a permanent redirect tends to put the new URL in search results, and a temporary one tends to keep the old URL there.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/technical-seo/canonical-tags-explained"') = 0;
UPDATE posts SET content = replace(content, 'so do not block the same URL in robots.txt.', 'so do not block the same URL in robots.txt. Our <a href="https://blog.scaryspiderseo.com/technical-seo/noindex-vs-disallow">noindex vs disallow comparison</a> shows which one to use when.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'robots-txt-guide' AND instr(content, 'so do not block the same URL in robots.txt.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/technical-seo/noindex-vs-disallow"') = 0;
UPDATE posts SET content = replace(content, 'Shops often generate thousands of near-identical URLs from internal search', 'Shops often generate <a href="https://blog.scaryspiderseo.com/technical-seo/duplicate-content-seo">thousands of near-identical URLs</a> from internal search'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'robots-txt-guide' AND instr(content, 'Shops often generate thousands of near-identical URLs from internal search') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/technical-seo/duplicate-content-seo"') = 0;
UPDATE posts SET content = replace(content, 'If it does not, ask whether it should exist at all.', 'If it does not, ask whether it should exist at all. Our <a href="https://blog.scaryspiderseo.com/technical-seo/orphan-pages-internal-linking">plan for fixing orphan pages</a> covers both options.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'xml-sitemap-guide' AND instr(content, 'If it does not, ask whether it should exist at all.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/technical-seo/orphan-pages-internal-linking"') = 0;
UPDATE posts SET content = replace(content, 'every page that uses that menu repeats the dead end.', 'every page that uses that menu repeats the dead end. Pages that lose their last working internal link become orphans, and <a href="https://blog.scaryspiderseo.com/technical-seo/orphan-pages-internal-linking">a simple internal linking plan</a> keeps that from happening.'), updated_at = CAST(strftime('%s','now') AS INTEGER) WHERE slug = 'find-and-fix-broken-links' AND instr(content, 'every page that uses that menu repeats the dead end.') > 0 AND instr(content, 'href="https://blog.scaryspiderseo.com/technical-seo/orphan-pages-internal-linking"') = 0;
